1	package vault
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"io/fs"
8		"os"
9		"path/filepath"
10		"sort"
11		"strings"
12	)
13	
14	// GCCandidate is a content object no longer referenced by the current name
15	// mapping or any snapshot, and therefore eligible for deletion.
16	type GCCandidate struct {
17		Digest string
18		Size   int64
19	}
20	
21	// GCReport summarizes one garbage collection pass. Candidates is always the
22	// full set of unreferenced objects found, sorted by digest; Deleted and Bytes
23	// record what was actually removed (zero for a dry run).
24	type GCReport struct {
25		Candidates []GCCandidate
26		Deleted    int
27		Bytes      int64
28	}
29	
30	// GC removes content objects that neither the current name mapping nor any
31	// saved snapshot still references. With dryRun set, nothing is deleted and
32	// the report only lists the candidates. The whole pass runs under the
33	// exclusive repository lock, so it always observes a complete, quiescent
34	// state: concurrent uploads, snapshot operations, downloads, and verifies
35	// either finish before the pass starts or wait until it is done.
36	//
37	// GC never creates or initializes a repository, never rewrites the index or
38	// any snapshot, and only ever deletes regular files directly inside objects/
39	// whose names are valid digests. Any unreadable or malformed reference
40	// (index or snapshot) aborts the pass before anything is deleted. If a
41	// deletion fails, the pass stops immediately; objects already removed stay
42	// removed and the rest remain as candidates for the next run.
43	func (s *Store) GC(dryRun bool) (GCReport, error) {
44		if strings.TrimSpace(s.root) == "" {
45			return GCReport{}, errors.New("root is required")
46		}
47		// withLock would create a missing root for mutating operations; GC must
48		// refuse an absent or uninitialized repository instead.
49		info, err := os.Stat(s.root)
50		switch {
51		case errors.Is(err, os.ErrNotExist):
52			return GCReport{}, fmt.Errorf("repository %q does not exist; run init first", s.root)
53		case err != nil:
54			return GCReport{}, err
55		case !info.IsDir():
56			return GCReport{}, fmt.Errorf("repository root %q is not a directory", s.root)
57		}
58		var report GCReport
59		err = s.withLock(true, func() error {
60			var gcErr error
61			report, gcErr = s.gcLocked(dryRun)
62			return gcErr
63		})
64		return report, err
65	}
66	
67	func (s *Store) gcLocked(dryRun bool) (GCReport, error) {
68		referenced, err := s.collectReferences()
69		if err != nil {
70			return GCReport{}, err
71		}
72		objectsDir := filepath.Join(s.root, "objects")
73		info, err := os.Lstat(objectsDir)
74		if err != nil {
75			return GCReport{}, fmt.Errorf("cannot inspect objects directory: %w", err)
76		}
77		if info.Mode()&os.ModeSymlink != 0 {
78			return GCReport{}, fmt.Errorf("objects path %q is a symbolic link", objectsDir)
79		}
80		if !info.IsDir() {
81			return GCReport{}, fmt.Errorf("objects path %q is not a directory", objectsDir)
82		}
83		dirents, err := os.ReadDir(objectsDir)
84		if err != nil {
85			return GCReport{}, fmt.Errorf("cannot read objects directory: %w", err)
86		}
87		candidates := []GCCandidate{}
88		for _, dirent := range dirents {
89			// Only regular files named by a valid digest are collectable;
90			// temp files, other names, subdirectories, and symlinks stay.
91			if !dirent.Type().IsRegular() || !isDigest(dirent.Name()) {
92				continue
93			}
94			if _, ok := referenced[dirent.Name()]; ok {
95				continue
96			}
97			fi, err := dirent.Info()
98			if err != nil {
99				return GCReport{}, fmt.Errorf("cannot stat object %q: %w", dirent.Name(), err)
100			}
101			candidates = append(candidates, GCCandidate{Digest: dirent.Name(), Size: fi.Size()})
102		}
103		sort.Slice(candidates, func(i, j int) bool { return candidates[i].Digest < candidates[j].Digest })
104		report := GCReport{Candidates: candidates}
105		if dryRun {
106			return report, nil
107		}
108		for _, candidate := range candidates {
109			if err := os.Remove(s.objectPath(candidate.Digest)); err != nil {
110				return report, fmt.Errorf("deleted %d objects (%d bytes), then failed to delete object %s: %w",
111					report.Deleted, report.Bytes, candidate.Digest, err)
112			}
113			report.Deleted++
114			report.Bytes += candidate.Size
115		}
116		return report, nil
117	}
118	
119	// collectReferences gathers every digest referenced by the current index and
120	// by all saved snapshots. Any record that cannot be read or fails validation
121	// is an error: GC must never guess whether a reference exists.
122	func (s *Store) collectReferences() (map[string]struct{}, error) {
123		referenced := map[string]struct{}{}
124		idx, err := s.loadStrict()
125		if err != nil {
126			return nil, fmt.Errorf("cannot collect references: current index is unusable: %w", err)
127		}
128		for key, entry := range idx.Entries {
129			if err := validateEntryRecord(key, entry); err != nil {
130				return nil, fmt.Errorf("current index is invalid: %w", err)
131			}
132			referenced[entry.Digest] = struct{}{}
133		}
134		dir := s.snapshotsDir()
135		info, err := os.Lstat(dir)
136		switch {
137		case errors.Is(err, os.ErrNotExist):
138			return referenced, nil
139		case err != nil:
140			return nil, fmt.Errorf("cannot inspect snapshots directory: %w", err)
141		case info.Mode()&os.ModeSymlink != 0:
142			return nil, fmt.Errorf("snapshots path %q is a symbolic link", dir)
143		case !info.IsDir():
144			return nil, fmt.Errorf("snapshots path %q is not a directory", dir)
145		}
146		err = filepath.WalkDir(dir, func(path string, d fs.DirEntry, walkErr error) error {
147			if walkErr != nil {
148				return walkErr
149			}
150			if d.Type()&os.ModeSymlink != 0 {
151				return fmt.Errorf("snapshots contain symbolic link %q", path)
152			}
153			if d.IsDir() {
154				return nil
155			}
156			if !d.Type().IsRegular() {
157				return fmt.Errorf("snapshots contain non-regular file %q", path)
158			}
159			if !strings.HasSuffix(d.Name(), ".json") {
160				return nil
161			}
162			rel, err := filepath.Rel(dir, path)
163			if err != nil {
164				return err
165			}
166			name := strings.TrimSuffix(filepath.ToSlash(rel), ".json")
167			if err := validateName(name); err != nil {
168				return fmt.Errorf("snapshot record %q does not map to a valid snapshot name: %w", path, err)
169			}
170			data, err := os.ReadFile(path)
171			if err != nil {
172				return err
173			}
174			var snap Snapshot
175			if err := json.Unmarshal(data, &snap); err != nil {
176				return fmt.Errorf("snapshot %q is corrupted: %w", name, err)
177			}
178			if snap.Entries == nil {
179				return fmt.Errorf("snapshot %q is corrupted: missing entries mapping", name)
180			}
181			if snap.Name != name {
182				return fmt.Errorf("snapshot %q is corrupted: recorded name %q does not match its location", name, snap.Name)
183			}
184			for key, entry := range snap.Entries {
185				if err := validateEntryRecord(key, entry); err != nil {
186					return fmt.Errorf("snapshot %q is corrupted: %w", name, err)
187				}
188				referenced[entry.Digest] = struct{}{}
189			}
190			return nil
191		})
192		if err != nil {
193			return nil, err
194		}
195		return referenced, nil
196	}
197	
198	// loadStrict reads the current index for GC. Unlike load it rejects a
199	// missing or null entries mapping, since GC cannot distinguish "no entries"
200	// from "references lost" in that case.
201	func (s *Store) loadStrict() (index, error) {
202		data, err := os.ReadFile(s.indexPath())
203		if errors.Is(err, os.ErrNotExist) {
204			return index{}, fmt.Errorf("repository %q is not initialized: index.json is missing", s.root)
205		}
206		if err != nil {
207			return index{}, err
208		}
209		var idx index
210		if err := json.Unmarshal(data, &idx); err != nil {
211			return index{}, err
212		}
213		if idx.Entries == nil {
214			return index{}, errors.New("missing entries mapping")
215		}
216		return idx, nil
217	}
218	
219	// validateEntryRecord checks one index or snapshot entry the same way
220	// restore validates snapshot entries: the map key must equal the recorded
221	// name, the name must be legal, the digest must be 64 lowercase hex
222	// characters, and the size must not be negative.
223	func validateEntryRecord(key string, entry Entry) error {
224		if entry.Name != key {
225			return fmt.Errorf("entry %q is filed under %q", entry.Name, key)
226		}
227		if err := validateName(entry.Name); err != nil {
228			return fmt.Errorf("invalid entry name %q", entry.Name)
229		}
230		if !isDigest(entry.Digest) {
231			return fmt.Errorf("entry %q has digest %q, want 64 lowercase hex characters", entry.Name, entry.Digest)
232		}
233		if entry.Size < 0 {
234			return fmt.Errorf("entry %q has negative size %d", entry.Name, entry.Size)
235		}
236		return nil
237	}
