405		// Restore must yield a consistent mapping containing base.txt.
406		if err := store.RestoreSnapshot("concurrent"); err != nil {
407			t.Fatal(err)
408		}
409		entries, err := store.List()
410		if err != nil {
411			t.Fatal(err)
412		}
413		if infos[0].Count != len(entries) {
414			t.Fatalf("restored %d entries, snapshot had %d", len(entries), infos[0].Count)
415		}
416		found := false
417		for _, entry := range entries {
418			if entry.Name == "base.txt" {
419				found = true
420			}
421			if !strings.HasPrefix(entry.Name, "base") && entry.Name != "later.txt" {
422				t.Fatalf("unexpected entry %q", entry.Name)
423			}
424		}
