func TestDecodePackageRejectsMalformedDocuments(t *testing.T) {
	src, _ := seedVault(t, map[string]string{"a.txt": "payload"})
	if _, err := New(src).CreateSnapshot("s"); err != nil {
		t.Fatal(err)
	}
	goodPath := filepath.Join(t.TempDir(), "s.pkg")
	mustExport(t, src, "s", "", goodPath)
	good, err := os.ReadFile(goodPath)
	if err != nil {
		t.Fatal(err)
	}

	// Build variants by editing the parsed JSON so each stays syntactically valid.
	var pkg Package
	if err := json.Unmarshal(good, &pkg); err != nil {
		t.Fatal(err)
	}
	d := digestOf("payload")
	encoded := base64.StdEncoding.EncodeToString([]byte("payload"))

	cases := map[string]func(){
		"unknown version":  func() { pkg.Version = 99 },
		"unknown format":   func() { pkg.Format = "something-else" },
		"bad snapshot name": func() {
			pkg.Snapshot.Name = "../escape"
			pkg.Snapshot.Entries["../escape"] = pkg.Snapshot.Entries["a.txt"]
			delete(pkg.Snapshot.Entries, "a.txt")
		},
		"bad digest":  func() { pkg.Objects[0].Digest = strings.Repeat("z", 64) },
		"negative size": func() {
			pkg.Objects[0].Size = -1
		},
		"checksum mismatch": func() {
			pkg.Objects[0].Digest = digestOf("other")
		},
		"size mismatch": func() {
			pkg.Objects[0].Size = 999
		},
		"bad base64": func() {
			pkg.Objects[0].Data = "!!!not base64!!!"
		},
		"missing content": func() {
			pkg.Objects = nil
		},
		"extra object": func() {
			pkg.Objects = append(pkg.Objects, PackageObject{
				Digest: digestOf("extra"), Size: 5, Data: base64.StdEncoding.EncodeToString([]byte("extra")),
			})
		},
	}
	for label, mutate := range cases {
		t.Run(label, func(t *testing.T) {
			variant := pkg
			mutate()
			t.Cleanup(func() { pkg = variant }) // not used across cases; harmless
			data, err := json.Marshal(&pkg)
			if err != nil {
				t.Fatal(err)
			}
			if _, err := decodePackage(data); err == nil {
				t.Fatalf("decode accepted %s", label)
			}
		})
		pkg = Package{}
		if err := json.Unmarshal(good, &pkg); err != nil {
			t.Fatal(err)
		}
		_ = d
		_ = encoded
	}

	t.Run("duplicate object record", func(t *testing.T) {
		dup := strings.Replace(string(good),
			`]`,
			fmt.Sprintf(`,%s]`, strings.TrimSpace(func() string {
				b, _ := json.MarshalIndent(pkg.Objects[0], "    ", "  ")
				return string(b)
			}())), 1)
		if _, err := decodePackage([]byte(dup)); err == nil {
			t.Fatal("duplicate object accepted")
		}
	})

	t.Run("duplicate json key", func(t *testing.T) {
		bad := strings.Replace(string(good), `"version": 1`, `"version": 1, "version": 1`, 1)
		if _, err := decodePackage([]byte(bad)); err == nil {
			t.Fatal("duplicate JSON key accepted")
		}
	})

	t.Run("unknown top-level field", func(t *testing.T) {
		bad := strings.Replace(string(good), `"version": 1`, `"version": 1, "sneaky": true`, 1)
		if _, err := decodePackage([]byte(bad)); err == nil {
			t.Fatal("unknown field accepted")
		}
	})
}

