			pkg.Snapshot.Entries["../escape"] = pkg.Snapshot.Entries["a.txt"]
			delete(pkg.Snapshot.Entries, "a.txt")
		},
		"bad digest":  func() { pkg.Objects[0].Digest = strings.Repeat("z", 64) },
