1	package vault
2	
3	import (
4		"crypto/sha256"
5		"encoding/base64"
6		"encoding/hex"
7		"encoding/json"
8		"errors"
9		"fmt"
10		"os"
11		"path/filepath"
12		"reflect"
13		"sort"
14	)
15	
16	// ExportResult summarizes a successful snapshot export.
17	type ExportResult struct {
18		Name    string
19		Entries int
20		Objects int
21	}
22	
23	// ImportResult summarizes a successful snapshot import.
24	type ImportResult struct {
25		Name       string
26		Entries    int
27		NewObjects int
28	}
29	
30	// ExportSnapshot writes the named snapshot, together with the content objects
31	// it needs, to output as a portable package.
32	//
33	// Without a base the package is complete: every referenced object is carried,
34	// and a digest shared by several entries is carried once. With base set to the
35	// name of another snapshot in the same repository, the package still records
36	// the target's complete mapping but only carries objects the base does not
37	// reference; an importer can only apply it on top of an identical base.
38	//
39	// Every object the target references is re-read and checked for recorded size
40	// and SHA-256, including objects omitted from a delta, so a corrupt snapshot
41	// record or a missing/damaged object never produces a successful package. The
42	// package is assembled in memory and written to a temporary file beside the
43	// destination before an atomic rename: a failed export never creates or
44	// alters the output file.
45	func (s *Store) ExportSnapshot(name, base, output string) (ExportResult, error) {
46		if err := validateName(name); err != nil {
47			return ExportResult{}, err
48		}
49		if base != "" {
50			if err := validateName(base); err != nil {
51				return ExportResult{}, err
52			}
53		}
54		if output == "" {
55			return ExportResult{}, errors.New("output is required")
56		}
57		var result ExportResult
58		err := s.withLock(true, func() error {
59			if err := s.initLocked(); err != nil {
60				return err
61			}
62			target, err := s.loadSnapshotRecord(name)
63			if err != nil {
64				return err
65			}
66			pkg := &Package{
67				Format:   packageFormat,
68				Version:  packageVersion,
69				Snapshot: target,
70				Objects:  []PackageObject{},
71			}
72			var baseSnap Snapshot
73			if base != "" {
74				var err error
75				baseSnap, err = s.loadSnapshotRecord(base)
76				if err != nil {
77					return fmt.Errorf("cannot use base snapshot: %w", err)
78				}
79				pkg.Base = &baseSnap
80			}
81	
82			// Verify every object the target references, reading each once. This
83			// includes objects the delta omits because the base references them:
84			// certifying the delta requires those to be intact too. Only objects
85			// the base does not reference are carried. Digests are processed in
86			// sorted order so the package layout and any failure message are
87			// deterministic.
88			carry := digestsReferenced(target.Entries)
89			if base != "" {
90				for digest := range digestsReferenced(baseSnap.Entries) {
91					delete(carry, digest)
92				}
93			}
94			for _, digest := range sortedDigests(target.Entries) {
95				content, size, err := s.readVerifiedObject(digest, target.Entries)
96				if err != nil {
97					return fmt.Errorf("snapshot %q references unusable object %s: %w", name, digest, err)
98				}
99				if _, included := carry[digest]; !included {
100					continue
101				}
102				pkg.Objects = append(pkg.Objects, PackageObject{
103					Digest: digest,
104					Size:   size,
105					Data:   base64.StdEncoding.EncodeToString(content),
106				})
107			}
108	
109			data, err := marshalPackage(pkg)
110			if err != nil {
111				return err
112			}
113			if err := writeFileAtomic(output, data, ".package-*"); err != nil {
114				return err
115			}
116			result = ExportResult{Name: name, Entries: len(target.Entries), Objects: len(pkg.Objects)}
117			return nil
118		})
119		if err != nil {
120			return ExportResult{}, err
121		}
122		return result, nil
123	}
124	
125	// ImportSnapshot imports a snapshot package produced by ExportSnapshot into an
126	// initialized repository.
127	//
128	// Import only adds the package's snapshot and any missing content objects; it
129	// never changes the current name mapping or any existing snapshot or object.
130	// A delta package is accepted only when the destination already contains a
131	// snapshot with the base name and byte-identical entry metadata, and every
132	// object the delta omits is present and intact. Healthy objects already in the
133	// destination are reused; re-importing a package whose snapshot is already
134	// present with identical metadata succeeds without creating a second copy. A
135	// same-named snapshot with different metadata is refused.
136	//
137	// All validation and reuse happens before anything is written. New objects
138	// land as complete files via temp-file-and-rename, and the snapshot record is
139	// renamed into place only after every object the mapping references has been
140	// verified, so a crash or write failure leaves at most unreferenced complete
141	// objects that a later gc removes and a retry succeeds; a partially imported
142	// snapshot can never be observed.
143	func (s *Store) ImportSnapshot(file string) (ImportResult, error) {
144		if file == "" {
145			return ImportResult{}, errors.New("file is required")
146		}
147		data, err := os.ReadFile(file)
148		if err != nil {
149			return ImportResult{}, err
150		}
151		pkg, err := decodePackage(data)
152		if err != nil {
153			return ImportResult{}, err
154		}
155		// Import targets an initialized repository; it never creates one the way
156		// mutating artifact commands do.
157		rootInfo, err := os.Stat(s.root)
158		switch {
159		case errors.Is(err, os.ErrNotExist):
160			return ImportResult{}, fmt.Errorf("repository %q does not exist; run init first", s.root)
161		case err != nil:
162			return ImportResult{}, err
163		case !rootInfo.IsDir():
164			return ImportResult{}, fmt.Errorf("repository root %q is not a directory", s.root)
165		}
166		var result ImportResult
167		err = s.withLock(true, func() error {
168			if _, err := os.Stat(s.indexPath()); errors.Is(err, os.ErrNotExist) {
169				return fmt.Errorf("repository %q is not initialized; run init first", s.root)
170			} else if err != nil {
171				return err
172			}
173			if err := rejectLinkedDirs(s.root); err != nil {
174				return err
175			}
176	
177			// A delta must sit on an exactly matching base: same snapshot name and
178			// identical entry metadata. A merely same-named snapshot, or objects
179			// that happen to share digests, is not a base.
180			if pkg.Base != nil {
181				existing, err := s.loadSnapshotRecord(pkg.Base.Name)
182				if err != nil {
183					return fmt.Errorf("delta base snapshot %q is unavailable: %w", pkg.Base.Name, err)
184				}
185				if !snapshotsEqual(existing, *pkg.Base) {
186					return fmt.Errorf("delta base snapshot %q does not match the package base", pkg.Base.Name)
187				}
188				if err := s.verifyReferencedObjects(pkg.Base.Name, existing.Entries); err != nil {
189					return fmt.Errorf("delta base snapshot %q is not fully present: %w", pkg.Base.Name, err)
190				}
191			}
192	
193			// A same-named destination snapshot is either an identical re-import
194			// (success, nothing added) or a collision (refusal to overwrite).
195			targetPath := s.snapshotPath(pkg.Snapshot.Name)
196			switch existing, statErr := os.Lstat(targetPath); {
197			case statErr == nil:
198				if existing.Mode()&os.ModeSymlink != 0 {
199					return fmt.Errorf("snapshot path %q is a symbolic link", targetPath)
200				}
201				current, err := s.loadSnapshotRecord(pkg.Snapshot.Name)
202				if err != nil {
203					return fmt.Errorf("snapshot %q already exists and is unusable: %w", pkg.Snapshot.Name, err)
204				}
205				if !snapshotsEqual(current, pkg.Snapshot) {
206					return fmt.Errorf("snapshot %q already exists with different metadata; refusing to overwrite", pkg.Snapshot.Name)
207				}
208				if err := s.verifyReferencedObjects(pkg.Snapshot.Name, pkg.Snapshot.Entries); err != nil {
209					return fmt.Errorf("snapshot %q already exists but is not fully restorable: %w", pkg.Snapshot.Name, err)
210				}
211				result = ImportResult{Name: pkg.Snapshot.Name, Entries: len(pkg.Snapshot.Entries), NewObjects: 0}
212				return nil
213			case errors.Is(statErr, os.ErrNotExist):
214				// Proceed to import.
215			default:
216				return statErr
217			}
218	
219			objects, err := pkg.materialize()
220			if err != nil {
221				return err
222			}
223	
224			// Phase 1, no writes: classify every carried object. Existing files
225			// must be healthy and are reused; a damaged one aborts the import and
226			// is reported by digest.
227			toAdd := make([]objectContent, 0, len(objects))
228			for _, obj := range objects {
229				path := s.objectPath(obj.digest)
230				info, err := os.Lstat(path)
231				switch {
232				case err == nil:
233					if info.Mode()&os.ModeSymlink != 0 {
234						return fmt.Errorf("object %s: object path is a symbolic link", obj.digest)
235					}
236					if !info.Mode().IsRegular() {
237						return fmt.Errorf("object %s: object path is not a regular file", obj.digest)
238					}
239					if _, _, err := s.readVerifiedObject(obj.digest, pkg.Snapshot.Entries); err != nil {
240						return fmt.Errorf("object %s already present but damaged: %w", obj.digest, err)
241					}
242				case errors.Is(err, os.ErrNotExist):
243					toAdd = append(toAdd, obj)
244				default:
245					return err
246				}
247			}
248	
249			// Phase 2: stage missing objects as complete, content-addressed files.
250			// A failure here leaves only unreferenced complete objects behind; a
251			// retry reuses them and finishes the import.
252			for _, obj := range toAdd {
253				if err := s.stageObject(obj.digest, obj.content); err != nil {
254					return err
255				}
256			}
257	
258			// Phase 3: the published mapping must be fully restorable. This covers
259			// reused objects, newly staged ones, and everything omitted by a delta.
260			if err := s.verifyReferencedObjects(pkg.Snapshot.Name, pkg.Snapshot.Entries); err != nil {
261				return err
262			}
263	
264			// Phase 4: publish the snapshot record last. This rename is the commit
265			// point; before it the imported snapshot simply does not exist.
266			if err := s.saveSnapshot(targetPath, pkg.Snapshot); err != nil {
267				return err
268			}
269			result = ImportResult{Name: pkg.Snapshot.Name, Entries: len(pkg.Snapshot.Entries), NewObjects: len(toAdd)}
270			return nil
271		})
272		if err != nil {
273			return ImportResult{}, err
274		}
275		return result, nil
276	}
277	
278	// loadSnapshotRecord reads and fully validates one stored snapshot: it must
279	// parse, carry a non-null entries mapping, record the same name it is filed
280	// under, and contain only valid entry records.
281	func (s *Store) loadSnapshotRecord(name string) (Snapshot, error) {
282		path := s.snapshotPath(name)
283		info, err := os.Lstat(path)
284		if errors.Is(err, os.ErrNotExist) {
285			return Snapshot{}, fmt.Errorf("snapshot %q not found", name)
286		}
287		if err != nil {
288			return Snapshot{}, err
289		}
290		if info.Mode()&os.ModeSymlink != 0 {
291			return Snapshot{}, fmt.Errorf("snapshot %q is a symbolic link", name)
292		}
293		if !info.Mode().IsRegular() {
294			return Snapshot{}, fmt.Errorf("snapshot %q is not a regular file", name)
295		}
296		data, err := os.ReadFile(path)
297		if err != nil {
298			return Snapshot{}, err
299		}
300		var snap Snapshot
301		if err := json.Unmarshal(data, &snap); err != nil {
302			return Snapshot{}, fmt.Errorf("snapshot %q is corrupted: %w", name, err)
303		}
304		if snap.Entries == nil {
305			return Snapshot{}, fmt.Errorf("snapshot %q is corrupted: missing entries mapping", name)
306		}
307		if snap.Name != name {
308			return Snapshot{}, fmt.Errorf("snapshot %q is corrupted: recorded name %q does not match its location", name, snap.Name)
309		}
310		for key, entry := range snap.Entries {
311			if err := validateEntryRecord(key, entry); err != nil {
312				return Snapshot{}, fmt.Errorf("snapshot %q is corrupted: %w", name, err)
313			}
314		}
315		return snap, nil
316	}
317	
318	// verifyReferencedObjects checks each distinct referenced digest once against
319	// the stored object's size and SHA-256.
320	func (s *Store) verifyReferencedObjects(snapshotName string, entries map[string]Entry) error {
321		for _, digest := range sortedDigests(entries) {
322			if _, _, err := s.readVerifiedObject(digest, entries); err != nil {
323				return fmt.Errorf("object %s needed by snapshot %q: %w", digest, snapshotName, err)
324			}
325		}
326		return nil
327	}
328	
329	// readVerifiedObject reads a content object and returns its bytes, confirming
330	// its SHA-256 digest and the size recorded for it in the given entries.
331	func (s *Store) readVerifiedObject(digest string, entries map[string]Entry) ([]byte, int64, error) {
332		path := s.objectPath(digest)
333		info, err := os.Lstat(path)
334		if err != nil {
335			return nil, 0, err
336		}
337		if info.Mode()&os.ModeSymlink != 0 {
338			return nil, 0, errors.New("object path is a symbolic link")
339		}
340		if !info.Mode().IsRegular() {
341			return nil, 0, errors.New("object path is not a regular file")
342		}
343		content, err := os.ReadFile(path)
344		if err != nil {
345			return nil, 0, err
346		}
347		sum := sha256.Sum256(content)
348		if actual := hex.EncodeToString(sum[:]); actual != digest {
349			return nil, 0, fmt.Errorf("content checksum is %s", actual)
350		}
351		if recordedSize, ok := sizeForDigest(entries, digest); ok && int64(len(content)) != recordedSize {
352			return nil, 0, fmt.Errorf("content is %d bytes, record says %d", len(content), recordedSize)
353		}
354		return content, int64(len(content)), nil
355	}
356	
357	// stageObject writes one missing object to a temp file and renames it into
358	// place. The content digest was verified when the package was decoded, so the
359	// final file is complete before it ever appears under its digest name.
360	func (s *Store) stageObject(digest string, content []byte) error {
361		tmp, err := os.CreateTemp(filepath.Join(s.root, "objects"), ".import-*")
362		if err != nil {
363			return err
364		}
365		tmpName := tmp.Name()
366		defer os.Remove(tmpName)
367		if _, err := tmp.Write(content); err != nil {
368			tmp.Close()
369			return fmt.Errorf("object %s: %w", digest, err)
370		}
371		if err := tmp.Close(); err != nil {
372			return fmt.Errorf("object %s: %w", digest, err)
373		}
374		if err := os.Rename(tmpName, s.objectPath(digest)); err != nil {
375			return fmt.Errorf("object %s: %w", digest, err)
376		}
377		return nil
378	}
379	
380	// rejectLinkedDirs makes sure an import can never stage files outside the
381	// repository through a replaced objects or snapshots directory.
382	func rejectLinkedDirs(root string) error {
383		for _, dir := range []string{filepath.Join(root, "objects"), filepath.Join(root, "snapshots")} {
384			if err := os.MkdirAll(dir, 0o755); err != nil {
385				return err
386			}
387			info, err := os.Lstat(dir)
388			if err != nil {
389				return err
390			}
391			if info.Mode()&os.ModeSymlink != 0 {
392				return fmt.Errorf("repository path %q is a symbolic link", dir)
393			}
394		}
395		return nil
396	}
397	
398	// writeFileAtomic writes data to a temporary file in the destination's
399	// directory and renames it over dest only after a complete flush. An existing
400	// destination is left untouched on any earlier failure.
401	func writeFileAtomic(dest string, data []byte, pattern string) error {
402		dir := filepath.Dir(dest)
403		if info, err := os.Lstat(dir); err != nil {
404			return err
405		} else if info.Mode()&os.ModeSymlink != 0 {
406			return fmt.Errorf("output directory %q is a symbolic link", dir)
407		}
408		tmp, err := os.CreateTemp(dir, pattern)
409		if err != nil {
410			return err
411		}
412		tmpName := tmp.Name()
413		defer os.Remove(tmpName)
414		if _, err := tmp.Write(data); err != nil {
415			tmp.Close()
416			return err
417		}
418		if err := tmp.Close(); err != nil {
419			return err
420		}
421		return os.Rename(tmpName, dest)
422	}
423	
424	// snapshotsEqual reports whether two snapshot records carry the same snapshot
425	// name and identical metadata for every entry.
426	func snapshotsEqual(a, b Snapshot) bool {
427		return reflect.DeepEqual(a.Entries, b.Entries) && a.Name == b.Name
428	}
429	
430	func sortedDigests(entries map[string]Entry) []string {
431		seen := map[string]struct{}{}
432		for _, entry := range entries {
433			seen[entry.Digest] = struct{}{}
434		}
435		out := make([]string, 0, len(seen))
436		for digest := range seen {
437			out = append(out, digest)
438		}
439		sort.Strings(out)
440		return out
441	}
442	
443	func sizeForDigest(entries map[string]Entry, digest string) (int64, bool) {
444		for _, entry := range entries {
445			if entry.Digest == digest {
446				return entry.Size, true
447			}
448		}
449		return 0, false
450	}
