// payloadToSnapshot validates one embedded snapshot record the same way
// restore and gc validate on-disk snapshots.
func payloadToSnapshot(scope string, p snapshotPayload) (Snapshot, error) {
	if err := validateName(p.Name); err != nil {
		return Snapshot{}, fmt.Errorf("invalid package: %s snapshot name %q is not a legal snapshot name", scope, p.Name)
	}
	if p.Entries == nil {
		return Snapshot{}, fmt.Errorf("invalid package: %s snapshot %q is missing its entries mapping", scope, p.Name)
	}
	for key, entry := range p.Entries {
		if err := validateEntryRecord(key, entry); err != nil {
			return Snapshot{}, fmt.Errorf("invalid package: %s snapshot %q: %w", scope, p.Name, err)
		}
	}
	return Snapshot{Name: p.Name, Entries: p.Entries}, nil
}

