	if _, err := New(src).CreateSnapshot("target"); err != nil {
		t.Fatal(err)
	}
	full := filepath.Join(t.TempDir(), "base.pkg")
	delta := filepath.Join(t.TempDir(), "target.pkg")
	mustExport(t, src, "base", "", full)
