func (s *Store) ensureSnapshotParent(path string) error {
	base := s.snapshotsDir()
	dir := filepath.Dir(path)
	rel, err := filepath.Rel(base, dir)
	if err != nil || rel == "." {
		if err != nil {
			return err
		}
		return nil
	}
	if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return errors.New("snapshot path escapes the snapshots directory")
	}
	cur := base
	for _, component := range strings.Split(rel, string(filepath.Separator)) {
		next := filepath.Join(cur, component)
		info, err := os.Lstat(next)
		switch {
		case errors.Is(err, os.ErrNotExist):
			if err := os.Mkdir(next, 0o755); err != nil {
				return err
			}
			// Re-stat: a component replaced by a symlink between the check and
			// the mkdir must not be followed.
			info, err = os.Lstat(next)
			if err != nil {
				return err
			}
			fallthrough
		case err != nil:
			return err
		default:
		}
		if info.Mode()&os.ModeSymlink != 0 || !info.IsDir() {
			return fmt.Errorf("snapshot path component %q is not a real directory", component)
		}
		cur = next
	}
	return nil
}

